import threading

class SafeCounter:
    def __init__(self):
        self._lock = threading.Lock()
        self._value = 0

    def _validate_int(self, n, allow_zero=True):
        if isinstance(n, bool) or not isinstance(n, int):
            raise ValueError("argument must be an integer")
        if allow_zero:
            if n < 0:
                raise ValueError("argument must be a non-negative integer")
        return n

    def increment(self, n=1):
        if isinstance(n, bool) or not isinstance(n, int):
            raise ValueError("n must be an integer")
        with self._lock:
            self._value += n

    def decrement(self, n=1):
        if isinstance(n, bool) or not isinstance(n, int):
            raise ValueError("n must be an integer")
        with self._lock:
            self._value -= n

    def value(self):
        with self._lock:
            return self._value

    def compare_and_set(self, expected, new):
        if isinstance(expected, bool) or not isinstance(expected, int):
            raise ValueError("expected must be an integer")
        if isinstance(new, bool) or not isinstance(new, int):
            raise ValueError("new must be an integer")
        with self._lock:
            if self._value == expected:
                self._value = new
                return True
            return False

    def transfer_to(self, other, n):
        if other is self:
            self._validate_int(n)
            return
        self._validate_int(n)
        first, second = (self, other) if id(self) < id(other) else (other, self)
        with first._lock:
            with second._lock:
                self._value -= n
                other._value += n
